INSERT INTO transfer_targets VALUES(130,'2026-summer','Martin Baturina','마르틴 바투리나',NULL,'Como','AM','CAM','MEDIUM-HIGH',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'틸레만스(→Man Utd)·로저스(→Chelsea) 유출 공백을 메울 창조형 미드필더 후보. 월드컵 잉글랜드전 골로 주가 상승, Como는 "매각 불가" 방침이었으나 최근 태도 완화 보도. 25/26 34경기 8골 4도움. [2026-07-27 21시 최신화] 빌라의 공식 오퍼(€50-55m)가 코모에 거절됨 확인(Football365/Football365 경유 코모 회장 발언) — 코모는 €80m 고수, 바이에른도 새로 경쟁 합류. 오퍼 제출까지는 갔으나 거절되어 HIGH 승격 요건(합의 단계) 미충족.','Sky Sports(Sky Italia 인용, 1티어): Villa 관심 확인, Como 요구 €80m; Athletic Jacob Tanswell(1티어): Villa 지출 상한 £40m 언급 — 재정 제약 캐비앗; Football365(코모 회장); Football Fancast; GiveMeSport; Yahoo Sports; CaughtOffside','MEDIUM-HIGH 유지 — 공식 오퍼 제출·거절까지 진행되었으나 밸류에이션 격차가 커 HIGH 미달.','바투리나');
INSERT INTO transfer_targets VALUES(133,'2026-summer','Harvey Barnes','하비 반스',NULL,'Newcastle United','LW','LM','MEDIUM-HIGH','44221X4111521011100101100',29.89999999999999858,65.40000000000000569,235,6.599999999999999645,'wm_widemid','Build-Up','wm_widemid','Build-Up',0.8129999999999999449,'빌라 좌측 와이드 보강 후보. 뉴캐슬과 2028년까지 계약 중이나 £38m 원 이적료 기준 협상 여지. 선수 본인이 미들랜즈 복귀(가족 근접) 희망한다는 전 CEO(Keith Wyness) 발언 다수, 25/26시즌 16골 활약 근거. [2026-07-27 21시 최신화] Keith Wyness(전 빌라 CEO, Football Insider 경유) — 선수 측 미들랜드 복귀 희망 확인. 뉴캐슬(하우 감독)은 잔류 희망하며 저항 중, £40m 밸류에이션. 램지-반스 스와프딜 가능성도 거론.','Football Insider247(2티어, 복수 기사: "closely watching"/"boost") ; TeamTalk(2티어) ; CaughtOffside(2티어) ; Keith Wyness(전 빌라 CEO) 발언(givemesport); Football Insider(Keith Wyness); TeamTalk; CaughtOffside; FootballTransferTavern','MEDIUM-HIGH 유지 — 선수 이적 희망 확인되나 뉴캐슬의 매각 저항으로 진전은 더딤.','반스');
INSERT INTO transfer_targets VALUES(134,'2026-summer','Lucas Bergvall','루카스 베리발',1391251,'Tottenham Hotspur','M','RDM','MEDIUM-HIGH','211230127X11273116X600100',67.29999999999999716,52.0,6,6.299999999999999823,NULL,NULL,'dm_dlp','Roaming',0.8060000000000000497,'[2026-07-27 신규] 틸레만스(맨유행 확정 유출) 대체 후보로 부상. Yahoo Sports "Sources: 빌라 재점화, 오픈 레이스"(Athletic 계열=1티어) + Football Insider·TeamTalk(2티어) 관심 보도, 이적료 ~£50m, 계약 2031. 경쟁 첼시·노팅엄 포레스트. ★댐퍼: Sky Michael Bridge — 스퍼스 "이번 여름 매각 불가" 입장 통보. 실측 THFC 최근 45+ 6경기(192pt, 시즌말 출전 급감=이적추진 정황): 중심 tool(67,52) 우중앙. RDM 커널 fit dm_dlp/Roaming 0.806(2위 boxcrasher/Balanced .77). LDM .43·CAM .50 부적합 → RDM 단일 등재(CM b2b .85지만 4-2-3-1에 CM 슬롯 없음). [2026-07-27 21시 최신화] Football Insider(2티어): 노팅엄 포레스트와 함께 선두 경쟁. 단 Sky Sports Michael Bridge(1티어)는 "이번 여름 이적 없다고 스퍼스가 선수에게 통보"라고 반박 보도 — 상충 유지. 선수 본인은 이적 희망 의사 재확인.','TransferFeed https://www.transferfeed.com/clubs/aston-villa/15 ; Yahoo Sports "Sources: Aston Villa to reignite Lucas Bergvall pursuit amid open race" ; footballinsider247.com ; SofaScore player/1391251 (6 THFC 45+ 2025-12~2026-04); Football Insider; TeamTalk; TheHardTackle; Sky Sports(Michael Bridge, 반박); DeadlineDayLive','MEDIUM-HIGH 유지 — 2티어 경쟁 보도 vs 1티어(Sky) 잔류 통보 반박이 상충, 등급 변동 없음.','베리발');
